// Analysé une seule fois au chargement du module.
export const COMMUNES = COMMUNES_DATA_RAW.split("\n").map((line) => {
  const [code, nom, dep, z] = line.split("|");
  return { code, nom, dep, zoneId: ZONE_CODE_MAP[z] };
});

// Normalisation pour une recherche insensible aux accents/casse.
export function normalizeStr(s) {
  return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

// Recherche de communes par préfixe de nom, avec priorité aux noms les plus
// courts (donc les plus probables : "Saint-Étienne" avant
// "Saint-Étienne-du-Bois") — voir bug corrigé lors du développement.
export function chercherCommunes(query, limite = 10) {
  const q = normalizeStr(query);
  if (q.length < 2) return [];
  const starts = [];
  const contains = [];
  for (const c of COMMUNES) {
    const n = normalizeStr(c.nom);
    if (n.startsWith(q)) { if (starts.length < 500) starts.push(c); }
    else if (n.includes(q)) { if (contains.length < 200) contains.push(c); }
  }
  const parRelevance = (a, b) => a.nom.length - b.nom.length || a.nom.localeCompare(b.nom, "fr");
  starts.sort(parRelevance);
  contains.sort(parRelevance);
  return [...starts, ...contains].slice(0, limite);
}
